Interface Figura
  Method Area() As Real;
EndInterface

Class Rectangulo Implements Figura
  Define largo, ancho As Real;
  Method Constructor(l As Real, a As Real)
    This.largo <- l;
    This.ancho <- a;
  EndMethod
  Method Area() As Real
    Return This.largo * This.ancho;
  EndMethod
EndClass

Class Cuadrado Implements Figura
  Define lado As Real;
  Method Constructor(l As Real)
    This.lado <- l;
  EndMethod
  Method Area() As Real
    Return This.lado * This.lado;
  EndMethod
EndClass

Class Triangulo Implements Figura
  Define base, alto As Real;
  Method Constructor(b As Real, a As Real)
    This.base <- b;
    This.alto <- a;
  EndMethod
  Method Area() As Real
    Return This.base * This.alto / 2;
  EndMethod
EndClass

Subroutine AreaDe<T: Figura>(figura As T) As Real
  Return figura.Area();
EndSubroutine

Algorithm Figuras
  Define tipo As String;
  Define primera, segunda As Real;
  Read tipo;
  If tipo = "cuadrado" Then
    Read primera;
    Write AreaDe(New Cuadrado(primera));
  Else
    Read primera;
    Read segunda;
    If tipo = "rectangulo" Then
      Write AreaDe(New Rectangulo(primera, segunda));
    Else
      Write AreaDe(New Triangulo(primera, segunda));
    EndIf
  EndIf
EndAlgorithm
